// scripts/migrate-user-identity.mjs
//
// One-time migration: separate the roster's own identity from Clerk's.
//
// BEFORE  users.id  held the Clerk userId (or a `pending_...` placeholder that
//         was later OVERWRITTEN with the Clerk id on acceptance), and
//         users.email carried a GLOBAL unique constraint — so one email address
//         could exist in exactly one organization across every customer.
// AFTER   users.id  is `usr_<uuid>`, generated by us and never reassigned.
//         users.clerk_user_id holds the Clerk identity, NULL until an invited
//         user accepts. Email is unique PER ORG.
//
// WHY THIS TALKS TO NEON DIRECTLY
// An earlier draft imported `db/index.js` the way the Netlify functions do.
// That path only resolves because Netlify's bundler maps .js -> .ts; plain node
// cannot load it, and pulling in tsx would drag the whole TypeScript schema in
// to run what is ultimately four ALTER statements and an UPDATE loop. Raw SQL
// against the Neon driver has no such dependency and cannot drift from the
// schema file, because it does not read it.
//
// Run order (guide 18c — the database moves first, the schema file follows):
//
//   1. node --env-file=.env scripts/migrate-user-identity.mjs            (plan)
//   2. node --env-file=.env scripts/migrate-user-identity.mjs --apply    (writes)
//   3. npx drizzle-kit push   — should report NO destructive diff on `users`
//
// Step 1 writes nothing. It prints exactly what step 2 would do and refuses to
// continue if anything would violate the new per-org unique indexes, so a
// collision surfaces as a readable list rather than as a failed index build.
//
// RE-RUNNABLE. A row already carrying a `usr_` id is skipped, and every DDL
// statement is IF EXISTS / IF NOT EXISTS. A partial failure can be resumed by
// running the same command again.

import { randomUUID } from 'crypto';
import { neon } from '@neondatabase/serverless';

const APPLY = process.argv.includes('--apply');
const log = (...a) => console.log(...a);

// The app database, under whichever name this environment uses. Checked in
// order; the first one set wins and is named in the output, because "which
// database did that just run against" must never be a guess.
const URL_VARS = ['NETLIFY_DATABASE_URL', 'DATABASE_URL', 'NEON_DATABASE_URL'];
const urlVar = URL_VARS.find((v) => process.env[v]);
if (!urlVar) {
    console.error(`\nNo database URL found. Set one of: ${URL_VARS.join(', ')}`);
    console.error('Run with:  node --env-file=.env scripts/migrate-user-identity.mjs');
    console.error('(Never `set -a; source .env` — a space after an "=" makes bash execute the value.)');
    process.exit(1);
}
const DB_URL = process.env[urlVar];

// Host only. Never the password, and never the whole string.
const hostOf = (u) => { try { return new URL(u).host; } catch { return '(unparseable url)'; } };

const sql = neon(DB_URL);

// The driver has returned a bare array in some versions and { rows } in others.
// Normalising once here means a driver bump cannot turn into a silent zero-row
// read that reports "nothing to migrate" and exits successfully.
const rowsOf = (r) => (Array.isArray(r) ? r : (r?.rows ?? []));

const CLERK_ID = /^user_[A-Za-z0-9]+$/;

async function ddl(statement, label) {
    if (!APPLY) { log(`   would run: ${label}`); return; }
    await statement();
    log(`   ran: ${label}`);
}

async function main() {
    log(`\nDatabase: ${hostOf(DB_URL)}   (from ${urlVar})`);
    log(APPLY ? '\n=== APPLYING ===\n' : '\n=== PLAN ONLY — nothing is written. Add --apply to execute. ===\n');

    // ── 0. Add the column ────────────────────────────────────────────────────
    await ddl(
        () => sql`ALTER TABLE users ADD COLUMN IF NOT EXISTS clerk_user_id text`,
        'ALTER TABLE users ADD COLUMN IF NOT EXISTS clerk_user_id text'
    );

    const hasColumn = rowsOf(await sql`
        SELECT 1 FROM information_schema.columns
         WHERE table_name = 'users' AND column_name = 'clerk_user_id'
    `).length > 0;

    // ── 1. Read the roster ───────────────────────────────────────────────────
    const rows = hasColumn
        ? rowsOf(await sql`SELECT id, org_id, email, name, clerk_user_id FROM users ORDER BY org_id, email`)
        : rowsOf(await sql`SELECT id, org_id, email, name, NULL::text AS clerk_user_id FROM users ORDER BY org_id, email`);

    log(`\nRoster rows: ${rows.length}`);
    const orgs = [...new Set(rows.map((r) => r.org_id))];
    log(`Organizations represented: ${orgs.length}\n`);
    if (rows.length === 0) {
        log('Nothing to migrate. If that is a surprise, check the database host above.');
        return;
    }

    // ── 2. Collision pre-check ───────────────────────────────────────────────
    // The new indexes are unique on (org_id, email) and (org_id, clerk_user_id).
    // Both must be clean BEFORE the index is built, or the build fails with a
    // Postgres error naming the constraint but not the offending rows.
    const seenEmail = new Map();
    const collisions = [];
    for (const r of rows) {
        const key = `${r.org_id}::${String(r.email || '').toLowerCase()}`;
        if (seenEmail.has(key)) collisions.push({ key, ids: [seenEmail.get(key), r.id] });
        else seenEmail.set(key, r.id);
    }
    if (collisions.length) {
        log('BLOCKED — duplicate (org_id, email) pairs would break the new unique index:\n');
        for (const c of collisions) log(`   ${c.key}\n      ${c.ids.join('\n      ')}`);
        log('\nResolve these first. Nothing was changed.');
        process.exit(1);
    }
    log('Collision check: clean — no duplicate (org_id, email) pairs.\n');

    // ── 3. Backfill clerk_user_id from the old id, then renumber ─────────────
    let linked = 0, unlinked = 0, renumbered = 0, skipped = 0;
    for (const r of rows) {
        if (String(r.id).startsWith('usr_')) { skipped++; continue; }
        const isClerk = CLERK_ID.test(String(r.id));
        const newId = 'usr_' + randomUUID();
        isClerk ? linked++ : unlinked++;
        renumbered++;

        log(`   ${r.email || r.name || '(no email)'}   [org ${String(r.org_id).slice(0, 12)}…]`);
        log(`      id             ${r.id}`);
        log(`                  -> ${newId}`);
        log(`      clerk_user_id -> ${isClerk ? r.id : 'NULL   ← never linked to Clerk'}`);

        if (APPLY) {
            await sql`
                UPDATE users
                   SET id            = ${newId},
                       clerk_user_id = ${isClerk ? String(r.id) : null},
                       updated_at    = NOW()
                 WHERE id = ${String(r.id)}
            `;
        }
    }
    log(`\nRenumbered: ${renumbered}   linked to Clerk: ${linked}   unlinked: ${unlinked}   already migrated: ${skipped}\n`);
    if (unlinked > 0) {
        log(`NOTE: ${unlinked} row(s) have no Clerk link. Those users cannot be identified`);
        log('      by the server until they sign in (which links them) or an Admin runs');
        log('      Sync from Clerk. If any of them has a working login today, that is');
        log('      roster drift and worth understanding before you apply.\n');
    }

    // ── 4. Swap the email constraint ─────────────────────────────────────────
    // Drop first, then build. Left the other way round, the global constraint
    // would keep rejecting a second org's copy of an address while appearing to
    // have been replaced.
    await ddl(() => sql`ALTER TABLE users DROP CONSTRAINT IF EXISTS users_email_unique`,
        'DROP CONSTRAINT users_email_unique   (the global one)');
    await ddl(() => sql`CREATE UNIQUE INDEX IF NOT EXISTS users_org_email_uq ON users (org_id, email)`,
        'CREATE UNIQUE INDEX users_org_email_uq (org_id, email)');
    await ddl(() => sql`CREATE UNIQUE INDEX IF NOT EXISTS users_org_clerk_uq ON users (org_id, clerk_user_id)`,
        'CREATE UNIQUE INDEX users_org_clerk_uq (org_id, clerk_user_id)');
    await ddl(() => sql`CREATE INDEX IF NOT EXISTS users_clerk_user_id_idx ON users (clerk_user_id)`,
        'CREATE INDEX users_clerk_user_id_idx (clerk_user_id)');

    log(APPLY
        ? '\nDone. Next: npx drizzle-kit push — verify no destructive diff on `users`.'
        : '\nPlan only — nothing was written. Re-run with --apply.');
}

main().then(() => process.exit(0)).catch((e) => {
    console.error('\nMigration failed:', e.message);
    console.error('Anything printed after a "ran:" line above WAS applied; the rest was not.');
    console.error('This script is re-runnable — fix the cause and run it again.');
    process.exit(1);
});
